import{_ as l,l as i,o as e,c as n,v as t,p as s,x as o,d,i as _,S as p}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"VQ-VAE","description":"","frontmatter":{"title":"VQ-VAE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vq-vae.md","filePath":"llm/vq-vae.md","lastUpdated":1789023840000}'),E={name:"llm/vq-vae.md"};function h(A,a,m,c,V,u){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="vq-vae" tabindex="-1">VQ-VAE <a class="header-anchor" href="#vq-vae" aria-label="Permalink to &quot;VQ-VAE&quot;">​</a></h1><div class="epigraph"><p>把连续隐变量换成码本里最近的向量，编码器输出就变成可当 token 的下标。生成模型于是可以在离散序列上做似然。</p><footer>—— van den Oord, Vinyals, Kavukcuoglu, VQ-VAE</footer></div><p><a href="/llm/retrieval-poisoning-defense">上一课</a>收束检索。本课程问像素如何进（生成式）模型。主干 <a href="/llm/vit-as-encoder">ViT</a> 给出连续 patch；生成还常要离散码，才能接自回归 LM。本课写 VQ-VAE。缺口是向量量化这一层，不是再讲卷积。后课 VQGAN 默认码本已经能重构，但不够锐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>像素上直接 softmax 不可行。连续 VAE 的 \\(z\\) 好解码、不好当词表。van den Oord 等人把编码器输出 \\(z_e(x)\\) 量化到码本 \\(\\{e_k\\}\\) 中最近项 \\(z_q\\)，解码器只看 \\(z_q\\)。下标 \\(k\\) 就是视觉 token。训练要同时学编码器、码本、解码器，并防止码本崩溃（只用少数项）。</p><p>与检索嵌入不同：这里的离散化是为了生成与似然，不是为了余弦近邻。</p><p><span class="marginnote">直通估计器让 \\(z_q\\) 的梯度抄到 \\(z_e\\)。码本用指数滑动平均或损失项更新。崩溃时重构还行、词表有效大小接近 1，后接 LM 会学到无信息序列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>损失：重构 + 码本承诺（commitment）使 \\(z_e\\) 贴近所选 \\(e_k\\)。下采样倍数决定 token 数：压得越狠，空间细节越少、序列越短。验收两件事：重构 FID/PSNR，以及码本使用率（熵、死码比例）。使用率低先修量化，再训上游 LM。</p>',9)),(e(),s(p,null,{default:o(()=>[_(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%20z_e%22%5D%0A%20%20ENC%20--%3E%20Q%5B%22%E6%9C%80%E8%BF%91%E7%A0%81%E5%AD%97%20z_q%22%5D%0A%20%20Q%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E9%87%8D%E6%9E%84%22%5D%0A%20%20Q%20--%3E%20ID%5B%22%E7%A6%BB%E6%95%A3%E4%B8%8B%E6%A0%87%20token%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>量化把连续空间划成 Voronoi 胞腔，胞腔中心是码字。生成时 LM 只建模胞腔下标的联合，细节交给解码器。若码本太小，胞腔过大，脸与文字糊；太大则序列变长、LM 更难。这是后课连续对离散的主轴。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>VQ-VAE 重构偏糊，因为损失是像素级、没有感知对抗。下一课 VQGAN 用 GAN 与感知损失改解码器，码本才够当高质量图像 tokenizer。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VQ-VAE 用最近码字把图像变成离散下标，供似然模型使用。</li><li>必须盯码本使用率，防止崩溃。</li><li>像素损失导致模糊，交给 VQGAN。</li><li>出处：van den Oord 等 VQ-VAE。</li></ul>',6))])}const q=l(E,[["render",h]]);export{v as __pageData,q as default};
